import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.time.temporal.ChronoUnit;

public class TimeDemo {
    public static void main(String[] args) {
        // Immutable date math
        LocalDate today = LocalDate.now();
        LocalDate nextWeek = today.plus(1, ChronoUnit.WEEKS);

        // Time zone manipulation
        ZonedDateTime zdtTokyo = ZonedDateTime.now(ZoneId.of("Asia/Tokyo"));

        // Thread-safe parsing and formatting
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
        String formattedDate = nextWeek.format(formatter);

        System.out.println("Formatted Next Week: " + formattedDate);
        System.out.println("Tokyo Time: " + zdtTokyo);
    }
}
